def set_wallpaper_macos(path: str) -> None:
    script = f'''
    tell application "System Events"
        try
            set desktop count to count of desktops
            repeat with theDesktop in desktops
                set picture of theDesktop to POSIX file "{path}"
            end repeat
        end try
    end tell
    '''
    try:
        subprocess.run(['osascript', '-e', script], capture_output=True, timeout=5)
    except Exception:
        pass

def set_wallpaper_linux(path: str) -> None:
    commands = [
        ['gsettings', 'set', 'org.gnome.desktop.background', 'picture-uri', f'file://{path}'],
        ['gsettings', 'set', 'org.gnome.desktop.background', 'picture-uri-dark', f'file://{path}'],
        ['xfconf-query', '-c', 'xfce4-desktop', '-p', '/backdrop/screen0/monitor0/workspace0/last-image', '-s', path],
        ['feh', '--bg-scale', path]
    ]
    for cmd in commands:
        try:
            subprocess.run(cmd, capture_output=True, timeout=5)
            break
        except Exception:
            continue

