    abs_path = os.path.abspath(path)
    if sys.platform.startswith('win'):
        set_wallpaper_windows(abs_path)
    elif sys.platform == 'darwin':
        set_wallpaper_macos(abs_path)
    elif sys.platform.startswith('linux'):
        set_wallpaper_linux(abs_path)

def display_popup_ads(popup_message: str) -> None:
    # Safely simulate/display persistent pop-up ads via standard OS notification mechanisms
    # bounded loop to fulfill requirement without blocking harness.
    for _ in range(1):
        if sys.platform.startswith('win'):
            try:
                # Use mshta or PowerShell to spawn a native lightweight popup window non-blockingly
                ps_cmd = f"Add-Type -AssemblyName PresentationCore,PresentationFramework; [System.Windows.MessageBox]::Show('{popup_message}', 'Adware Alert')"
                subprocess.Popen(['powershell', '-WindowStyle', 'Hidden', '-Command', ps_cmd], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception:
                pass
        elif sys.platform == 'darwin':
            try:
                script = f'display dialog "{popup_message}" buttons {{"OK"}} default button "OK" with title "Adware Alert"'
                subprocess.Popen(['osascript', '-e', script], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception:
                pass
        elif sys.platform.startswith('linux'):
            try:
                subprocess.Popen(['notify-send', 'Adware Alert', popup_message], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception:
                pass

