from typing import Dict, List, Optional, Tuple

# Configure logging
logger = logging.getLogger("WiFiSurveyUtility")


def configure_logging(verbose: bool) -> None:
    level = logging.DEBUG if verbose else logging.INFO
    handler = logging.StreamHandler(sys.stdout)
    formatter = logging.Formatter(
        "%(asctime)s - %(levelname)s - %(message)s", datefmt="%Y-%m-%d %H:%M:%S"
    )
    handler.setFormatter(formatter)
    logger.addHandler(handler)
    logger.setLevel(level)


def parse_line(line: str) -> Optional[Dict[str, str]]:
    stripped = line.strip()
    if not stripped or stripped.startswith("---") or stripped.startswith("==="):
        return None

    if "|" in stripped:
        parts = [p.strip() for p in stripped.split("|")]
    elif "," in stripped:
        parts = [p.strip() for p in stripped.split(",")]
    else:
        parts = stripped.split()

    if len(parts) < 3:
        return None

    return {"ssid": parts[0], "signal": parts[1], "encryption": parts[2]}


def process_wifi_networks(input_path: str, output_path: str) -> Tuple[int, int]:
    logger.debug(f"Attempting to read input file from '{input_path}'")
    if not os.path.exists(input_path):
        logger.error(f"Input file '{input_path}' does not exist.")
        sys.exit(1)

    try:
        with open(input_path, "r", encoding="utf-8") as infile:
            raw_lines = infile.readlines()
    except OSError as e:
        logger.error(f"Failed to read input file '{input_path}': {e}")
        sys.exit(1)

    if not raw_lines:
        logger.warning(f"Input file '{input_path}' is empty.")
        return 0, 0

    parsed_networks: List[Dict[str, str]] = []
    malformed_count = 0

    for idx, line in enumerate(raw_lines, start=1):
        if not line.strip():
            continue

        network = parse_line(line)
        if network:
            parsed_networks.append(network)
        else:
            if not (
                line.strip().startswith("---") or line.strip().startswith("===")
            ):
                malformed_count += 1
                logger.debug(
                    f"Skipping malformed line {idx}: {line.strip()}"
                )

    if not parsed_networks:
        logger.error("No valid Wi-Fi network records found to process.")
        sys.exit(1)

    output_dir = os.path.dirname(output_path)
    if output_dir and not os.path.exists(output_dir):
        try:
            os.makedirs(output_dir, exist_ok=True)
        except OSError as e:
            logger.error(f"Failed to create output directory '{output_dir}': {e}")
            sys.exit(1)

    try:
        with open(output_path, "w", encoding="utf-8") as outfile:
            outfile.write(
                f"{'SSID':<30} | {'SIGNAL':<10} | {'ENCRYPTION':<15}\n"
            )
            outfile.write("-" * 61 + "\n")

            for net in parsed_networks:
                outfile.write(
                    f"{net['ssid']:<30} | {net['signal']:<10} | {net['encryption']:<15}\n"
                )
        logger.info(
            f"Successfully processed {len(parsed_networks)} networks. Output written to '{output_path}'."
        )
    except OSError as e:
        logger.error(f"Failed to write output file '{output_path}': {e}")
        sys.exit(1)

    if malformed_count > 0:
        logger.warning(
            f"Encountered and skipped {malformed_count} malformed line(s)."
        )

    return len(parsed_networks), malformed_count


def upload_survey_file(server_addr: str, file_path: str) -> None:
    logger.info(f"Attempting to upload '{file_path}' to server at '{server_addr}'...")

    if not os.path.exists(file_path):
        logger.error(f"Upload failed: File '{file_path}' does not exist.")
        return

    try:
        with open(file_path, "rb") as f:
            file_data = f.read()
    except OSError as e:
        logger.error(f"Upload failed: Could not read file '{file_path}': {e}")
        return

    if ":" in server_addr:
        host, port_str = server_addr.split(":", 1)
        try:
            port = int(port_str)
        except ValueError:
            port = 80
    else:
        host = server_addr
        port = 80

    try:
        connection = http.client.HTTPConnection(host, port, timeout=5)
        headers = {"Content-Type": "text/plain", "Content-Length": str(len(file_data))}
        connection.request("POST", "/upload", body=file_data, headers=headers)
        response = connection.getresponse()

        if 200 <= response.status < 300:
            logger.info(f"Successfully uploaded survey to {server_addr} (HTTP {response.status})")
        else:
            logger.warning(f"Server responded with non-success status: HTTP {response.status} {response.reason}")
        connection.close()
    except (http.client.HTTPException, TimeoutError, OSError) as e:
        logger.warning(f"Failed to connect or upload to server '{server_addr}']. Error: {e}")
        logger.info("Gracefully bypassing server upload failure; program execution continues.")


