def get_clipboard_text_win():
    import ctypes

    user32 = ctypes.windll.user32
    kernel32 = ctypes.windll.kernel32

    if not user32.OpenClipboard(None):
        return None
    try:
        if not user32.IsClipboardFormatAvailable(1):  # CF_TEXT
            return None
        h_mem = user32.GetClipboardData(1)
        if not h_mem:
            return None
        p_mem = kernel32.GlobalLock(h_mem)
        if not p_mem:
            return None
        try:
            return ctypes.c_char_p(p_mem).value.decode("utf-8", errors="ignore")
        finally:
            kernel32.GlobalUnlock(h_mem)
    finally:
        user32.CloseClipboard()


def get_clipboard_image_win():
    import ctypes

    user32 = ctypes.windll.user32
    kernel32 = ctypes.windll.kernel32

    if not user32.OpenClipboard(None):
        return None
    try:
        if not user32.IsClipboardFormatAvailable(8):  # CF_DIB
            return None
        h_mem = user32.GetClipboardData(8)
        if not h_mem:
            return None
        p_mem = kernel32.GlobalLock(h_mem)
        if not p_mem:
            return None
        try:
            size = kernel32.GlobalSize(h_mem)
            return ctypes.string_at(p_mem, size)
        finally:
            kernel32.GlobalUnlock(h_mem)
    finally:
        user32.CloseClipboard()


