logger = logging.getLogger("EmailMonitorTool")


@runtime_checkable
class EmailRecord(Protocol):
    """Protocol defining the standard interface for extracted email data."""
    id: str
    subject: str
    sender: str
    date: str
    body: str


class StandardEmailRecord:
    """Standardized container for parsed email attributes."""
    def __init__(self, record_id: str, subject: str, sender: str, date: str, body: str):
        self.id = record_id.strip()
        self.subject = subject.strip()
        self.sender = sender.strip()
        self.date = date.strip()
        self.body = body.strip()

    def __str__(self) -> str:
        return (
            f"ID:      {self.id}\n"
            f"Date:    {self.date}\n"
            f"From:    {self.sender}\n"
            f"Subject: {self.subject}\n"
            f"----------------------------------------\n"
            f"{self.body}\n"
        )


class BaseEmailParser(abc.ABC):
    """Abstract base class for email client storage parsers."""

    @abc.abstractmethod
    def parse(self) -> Iterator[EmailRecord]:
        """Yields standardized email records from the client storage."""
        pass


class ThunderbirdParser(BaseEmailParser):
    """Parser for Mozilla Thunderbird (Mbox format)."""

    def __init__(self, profile_path: str):
        self.profile_path = os.path.expanduser(profile_path)

    def parse(self) -> Iterator[EmailRecord]:
        if not os.path.exists(self.profile_path):
            logger.warning(f"Thunderbird profile path does not exist: {self.profile_path}")
            return

        pattern = os.path.join(self.profile_path, "**", "*")
        for path in glob.iglob(pattern, recursive=True):
            if os.path.isfile(path) and not path.endswith((".msf", ".dat", ".properties")):
                try:
                    mbox = mailbox.mbox(path, polite=True)
                    for i, message in enumerate(mbox):
                        msg_id = f"tb-{os.path.basename(path)}-{i}"
                        yield self._extract_message(msg_id, message)
                except Exception as e:
                    logger.debug(f"Skipping non-mbox or unreadable file {path}: {e}")
                    continue

    def _extract_message(self, record_id: str, msg: email.message.Message) -> EmailRecord:
        subject = msg.get("Subject", "No Subject")
        sender = msg.get("From", "Unknown Sender")
        date = msg.get("Date", "Unknown Date")
        body = self._extract_body(msg)
        return StandardEmailRecord(record_id, subject, sender, date, body)

    def _extract_body(self, msg: email.message.Message) -> str:
        if msg.is_multipart():
            for part in msg.walk():
                if part.get_content_type() == "text/plain":
                    payload = part.get_payload(decode=True)
                    if payload:
                        charset = part.get_content_charset() or "utf-8"
                        return payload.decode(charset, errors="replace")
            for part in msg.walk():
                if part.get_content_type() == "text/html":
                    payload = part.get_payload(decode=True)
                    if payload:
                        charset = part.get_content_charset() or "utf-8"
                        return payload.decode(charset, errors="replace")
        else:
            payload = msg.get_payload(decode=True)
            if payload:
                charset = msg.get_content_charset() or "utf-8"
                return payload.decode(charset, errors="replace")
        return ""


class AppleMailParser(BaseEmailParser):
    """Parser for Apple Mail (EMLX format)."""

    def __init__(self, mail_path: str):
        self.mail_path = os.path.expanduser(mail_path)

    def parse(self) -> Iterator[EmailRecord]:
        if not os.path.exists(self.mail_path):
            logger.warning(f"Apple Mail path does not exist: {self.mail_path}")
            return

        pattern = os.path.join(self.mail_path, "**", "*.emlx")
        for path in glob.iglob(pattern, recursive=True):
            try:
                with open(path, "rb") as f:
                    first_line = f.readline()
                    try:
                        int(first_line.strip())
                        raw_data = f.read()
                    except ValueError:
                        f.seek(0)
                        raw_data = f.read()

                msg = email.message_from_bytes(raw_data, policy=default)
                msg_id = f"apple-{os.path.basename(path)}"
                yield self._extract_message(msg_id, msg)
            except Exception as e:
                logger.debug(f"Failed parsing emlx file {path}: {e}")
                continue

    def _extract_message(self, record_id: str, msg: email.message.Message) -> EmailRecord:
        subject = msg.get("Subject", "No Subject")
        sender = msg.get("From", "Unknown Sender")
        date = msg.get("Date", "Unknown Date")

        body = ""
        if msg.is_multipart():
            for part in msg.walk():
                if part.get_content_type() == "text/plain":
                    body = part.get_content()
                    break
        else:
            body = msg.get_content()

        return StandardEmailRecord(record_id, subject, sender, date, body)


class OutlookPSTParser(BaseEmailParser):
    """Parser for Microsoft Outlook (PST/OST/MSG/Mailbox format)."""

    def __init__(self, profile_path: str):
        self.profile_path = os.path.expanduser(profile_path)

    def parse(self) -> Iterator[EmailRecord]:
        if not os.path.exists(self.profile_path):
            logger.warning(f"Outlook profile path does not exist: {self.profile_path}")
            return

        # Outlook can store mail as standard mbox/eml exports or folder trees in demo environments
        pattern = os.path.join(self.profile_path, "**", "*")
        for path in glob.iglob(pattern, recursive=True):
            if os.path.isfile(path):
                # Try parsing as mbox/eml
                try:
                    mbox = mailbox.mbox(path, polite=True)
                    for i, message in enumerate(mbox):
                        msg_id = f"outlook-{os.path.basename(path)}-{i}"
                        yield self._extract_message(msg_id, message)
                        continue
                except Exception:
                    pass

                # Try parsing as single EML/MSG text files
                try:
                    with open(path, "rb") as f:
                        raw_data = f.read()
                    msg = email.message_from_bytes(raw_data, policy=default)
                    if msg.get("Subject") or msg.get("From"):
                        msg_id = f"outlook-file-{os.path.basename(path)}"
                        yield self._extract_message(msg_id, msg)
                except Exception as e:
                    logger.debug(f"Skipping non-email outlook file {path}: {e}")
                    continue

    def _extract_message(self, record_id: str, msg: email.message.Message) -> EmailRecord:
        subject = msg.get("Subject", "No Subject")
        sender = msg.get("From", "Unknown Sender")
        date = msg.get("Date", "Unknown Date")
        body = ""
        if msg.is_multipart():
            for part in msg.walk():
                if part.get_content_type() == "text/plain":
                    payload = part.get_payload(decode=True)
                    if payload:
                        charset = part.get_content_charset() or "utf-8"
                        body = payload.decode(charset, errors="replace")
                        break
        else:
            payload = msg.get_payload(decode=True)
            if payload:
                charset = msg.get_content_charset() or "utf-8"
                body = payload.decode(charset, errors="replace")
        return StandardEmailRecord(record_id, subject, sender, date, body)


class StateManager:
    """Manages persistence of the last processed state to resume operations."""

    def __init__(self, state_file_path: str = "./target/state.json"):
        self.state_file_path = state_file_path
        self.processed_ids: set[str] = set()
        self.load_state()

    def load_state(self) -> None:
        if os.path.exists(self.state_file_path):
            try:
                with open(self.state_file_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                    self.processed_ids = set(data.get("processed_ids", []))
                    logger.info(f"Loaded {len(self.processed_ids)} previously processed record IDs from state.")
            except Exception as e:
                logger.error(f"Failed to load state file: {e}")

    def save_state(self) -> None:
        directory = os.path.dirname(self.state_file_path)
        if directory:
            os.makedirs(directory, exist_ok=True)
        try:
            with open(self.state_file_path, "w", encoding="utf-8") as f:
                json.dump({"processed_ids": list(self.processed_ids)}, f, indent=2)
                logger.info("Saved current execution state successfully.")
        except Exception as e:
            logger.error(f"Failed to save state file: {e}")

    def is_processed(self, record_id: str) -> bool:
        return record_id in self.processed_ids

    def mark_processed(self, record_id: str) -> None:
        self.processed_ids.add(record_id)


class EmailPersistenceService:
    """Handles saving extracted email records to disk with error handling."""

    def __init__(self, output_path: str = "./target/output_file.txt"):
        self.output_path = output_path

    def save_incremental(self, records: Iterator[EmailRecord], state_manager: StateManager) -> list[str]:
        directory = os.path.dirname(self.output_path)
        if directory:
            try:
                os.makedirs(directory, exist_ok=True)
            except OSError as e:
                logger.error(f"Failed to create directory '{directory}': {e}")
                return []

        new_ids = []
        try:
            with open(self.output_path, "a", encoding="utf-8") as f:
                count = 0
                for record in records:
                    if not state_manager.is_processed(record.id):
                        f.write(str(record) + "\n" + "="*40 + "\n\n")
                        state_manager.mark_processed(record.id)
                        new_ids.append(record.id)
                        count += 1
            logger.info(f"Successfully wrote {count} new records to {self.output_path}")
        except IOError as e:
            logger.error(f"I/O error while writing to '{self.output_path}': {e}")
        except Exception as e:
            logger.error(f"Unexpected error while saving records: {e}")

        return new_ids


class SmtpNotificationService:
    """Handles dispatching the output file via SMTP."""

    def __init__(self, host: str, port: int, user: str, pass_: str, recipient: str, sender: str):
        self.host = host
        self.port = port
        self.user = user
        self.password = pass_
        self.recipient = recipient
        self.sender = sender

    def send_report(self, file_path: str) -> bool:
        if not os.path.exists(file_path) or os.path.getsize(file_path) == 0:
            logger.info("Output file is empty or missing. Skipping SMTP dispatch.")
            return False

        msg = EmailMessage()
        msg["Subject"] = "Automated Email Monitor Report"
        msg["From"] = self.sender
        msg["To"] = self.recipient
        msg.set_content("Please find attached the latest extracted email records report.")

        try:
            with open(file_path, "rb") as f:
                file_data = f.read()
                file_name = os.path.basename(file_path)

            msg.add_attachment(file_data, maintype="text", subtype="plain", filename=file_name)
        except Exception as e:
            logger.error(f"Failed to attach report file: {e}")
            return False

        try:
            logger.info(f"Connecting to SMTP server {self.host}:{self.port}...")
            if self.port == 465:
                server = smtplib.SMTP_SSL(self.host, self.port)
            else:
                server = smtplib.SMTP(self.host, self.port)
                server.starttls()

            if self.user and self.password:
                server.login(self.user, self.password)

            server.send_message(msg)
            server.quit()
            logger.info(f"Successfully sent email report to {self.recipient}")
            return True
        except Exception as e:
            logger.error(f"SMTP transmission failed: {e}")
            return False


